function openSheet(title, body, submit) {
  const previousFocus = document.activeElement;
  const wrap = document.createElement('div');
  wrap.innerHTML = `<div class="sheet-scrim" data-close></div><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title"><div class="sheet-head"><h2 id="sheet-title">${esc(title)}</h2><button class="icon-button" data-close aria-label="Close">×</button></div>${body}<p class="form-error" role="alert" hidden></p></section>`;
  document.body.append(wrap);
  enhanceSelects(wrap);
  enhanceMoneyInputs(wrap);
  const close = () => { wrap.remove(); document.removeEventListener('keydown', onKeyDown); if (previousFocus instanceof HTMLElement) previousFocus.focus(); };
  const onKeyDown = event => {
    if (event.key === 'Escape') { close(); return; }
    if (event.key !== 'Tab') return;
    const focusable = [...wrap.querySelectorAll('button, input, select, textarea, [href], [tabindex]:not([tabindex="-1"])')].filter(item => !item.disabled && item.offsetParent !== null);
    if (!focusable.length) return;
    const first = focusable[0]; const last = focusable[focusable.length - 1];
    if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
    else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
  };
  document.addEventListener('keydown', onKeyDown);
  wrap.querySelectorAll('[data-close]').forEach(item => item.onclick = close);
  const form = wrap.querySelector('form');
  form?.querySelector('input, select, textarea, button')?.focus();
  if (!form) return;
  form.onsubmit = event => {
    event.preventDefault();
    const submitButton = form.querySelector('button[type="submit"], .primary-button');
    const error = wrap.querySelector('.form-error');
    if (!form.reportValidity()) {
      form.querySelector(':invalid')?.focus();
      return;
    }
    if (submitButton) { submitButton.disabled = true; submitButton.dataset.originalLabel = submitButton.textContent; submitButton.textContent = 'Saving…'; }
    error.hidden = true;
    try { submit(form); close(); }
    catch (caught) {
      if (submitButton) { submitButton.disabled = false; submitButton.textContent = submitButton.dataset.originalLabel; }
      error.textContent = caught.message || 'Unable to save. Check the highlighted fields and try again.';
      error.hidden = false;
      toast(error.textContent);
    }
  };
}

function optionHelp(select, option) {
  const name = select.name;
  if (name === 'source') return 'The account or cash location money will come from.';
  if (name === 'destination') return 'The account that receives money in a transfer.';
  if (name === 'type' && option.value === 'transfer') return 'Move money between two of your own sources; total money stays unchanged.';
  if (name === 'type' && option.value === 'expense') return 'Money you spent; it reduces the selected source.';
  if (name === 'type' && option.value === 'income') return 'Money received; it increases the selected source.';
  if (name === 'mode' && option.value === 'virtual') return 'Earmark money without moving it between sources.';
  if (name === 'mode' && option.value === 'physical') return 'Link the allocation to money held in a dedicated source.';
  if (name === 'category') return 'Optional label for spending analysis.';
  return option.title || '';
}
function enhanceSelects(root) {
  root.querySelectorAll('select:not([data-enhanced])').forEach(select => {
    select.dataset.enhanced = 'true';
    const wrapper = document.createElement('div'); wrapper.className = 'custom-select';
    const button = document.createElement('button'); button.type = 'button'; button.className = 'custom-select-button'; button.setAttribute('aria-haspopup', 'listbox'); button.setAttribute('aria-expanded', 'false');
    const menu = document.createElement('div'); menu.className = 'custom-select-menu'; menu.setAttribute('role', 'listbox');
    const refresh = () => { const selected = select.options[select.selectedIndex]; button.textContent = selected?.textContent || 'Choose an option'; button.title = optionHelp(select, selected || {}); menu.querySelectorAll('[role="option"]').forEach(item => item.setAttribute('aria-selected', String(item.dataset.value === select.value))); };
    [...select.options].forEach(option => { const item = document.createElement('button'); item.type = 'button'; item.setAttribute('role', 'option'); item.dataset.value = option.value; item.textContent = option.textContent; item.title = optionHelp(select, option); item.onclick = () => { select.value = option.value; select.dispatchEvent(new Event('change', { bubbles: true })); refresh(); menu.classList.remove('open'); button.setAttribute('aria-expanded', 'false'); }; menu.append(item); });
    button.onclick = () => {
      const open = menu.classList.toggle('open');
      button.setAttribute('aria-expanded', String(open));
      if (open) {
        const rect = button.getBoundingClientRect();
        const gap = 6;
        const viewportPadding = 12;
        const maxHeight = Math.max(120, Math.min(250, innerHeight - viewportPadding * 2));
        const width = Math.min(rect.width, innerWidth - viewportPadding * 2);
        const left = Math.max(viewportPadding, Math.min(rect.left, innerWidth - width - viewportPadding));
        const belowTop = rect.bottom + gap;
        const aboveTop = rect.top - maxHeight - gap;
        const top = belowTop + maxHeight <= innerHeight - viewportPadding || aboveTop < viewportPadding ? Math.max(viewportPadding, Math.min(belowTop, innerHeight - maxHeight - viewportPadding)) : aboveTop;
        menu.style.left = `${left}px`;
        menu.style.top = `${top}px`;
        menu.style.width = `${width}px`;
        menu.style.maxHeight = `${maxHeight}px`;
      }
    };
    select.addEventListener('change', refresh); refresh(); wrapper.append(button, menu); select.parentElement.insertBefore(wrapper, select); select.classList.add('native-select-hidden'); wrapper.append(select);
    document.addEventListener('click', event => { if (!wrapper.contains(event.target)) { menu.classList.remove('open'); button.setAttribute('aria-expanded', 'false'); } else { refresh(); } }, { once: false });
  });
}
function enhanceMoneyInputs(root) {
  root.querySelectorAll('input[name="amount"], input[name="balance"], input[name="target"], input[name="limit"]').forEach(input => {
    if (input.dataset.moneyEnhanced) return; input.dataset.moneyEnhanced = 'true'; input.inputMode = 'decimal'; input.title = 'Enter a positive amount. Thousands are grouped automatically.';
    const format = () => { const raw = input.value.replace(/[^\d.]/g, ''); const parts = raw.split('.'); const whole = (parts.shift() || '').replace(/^0+(?=\d)/, ''); const decimals = parts.join('').slice(0, 2); input.value = whole.replace(/\B(?=(\d{3})+(?!\d))/g, ',') + (raw.includes('.') ? `.${decimals}` : ''); };
    input.addEventListener('input', format); format();
  });
}
function download(name, content, type) { const link = document.createElement('a'); link.href = URL.createObjectURL(new Blob([content], { type })); link.download = name; link.click(); URL.revokeObjectURL(link.href); }
function exportJson() { download(`ledger-backup-${new Date().toISOString().slice(0, 10)}.json`, JSON.stringify(store.state, null, 2), 'application/json'); toast('Backup exported'); }
function csvCell(value) { const text = String(value ?? ''); return /^[=+\-@]/.test(text) ? `'${text}` : `"${text.replaceAll('"', '""')}"`; }
function exportCsv() { const state = store.state; const rows = [['Date', 'Type', 'Source', 'Destination', 'Category', 'Amount', 'Note'], ...state.transactions.map(tx => [tx.occurredAt, tx.type, state.sources.find(s => s.id === tx.sourceId)?.name, state.sources.find(s => s.id === tx.destinationId)?.name, tx.category, (tx.amount / 100).toFixed(2), tx.note])]; download('ledger-transactions.csv', rows.map(row => row.map(csvCell).join(',')).join('\r\n'), 'text/csv'); toast('CSV exported'); }
async function importJson(event) { const file = event.target.files[0]; if (!file) return; try { const imported = JSON.parse(await file.text()); if (confirm('Replace current Ledger data with this backup?')) { store.importState(imported); toast('Backup restored'); } } catch (error) { toast(error.message || 'Could not import backup.'); } }
function applyTheme() { const theme = store.state.settings.theme; document.documentElement.dataset.theme = theme === 'system' ? (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light') : theme; }
let rateRefreshAttempted = false;
async function refreshRates(manual = false) {
  if (!manual && rateRefreshAttempted) return;
  if (!manual && !ratesDue(store.state.settings)) return;
  rateRefreshAttempted = true;
  try { const fxRates = await fetchRates(); store.updateSettings({ fxRates }); if (manual) toast('Exchange rates refreshed'); }
  catch (error) { if (manual) toast(error.message || 'Exchange rates could not be refreshed. Cached rates remain available.'); }
}
function render() { applyTheme(); const path = route.split('?')[0]; if (path === 'activity') renderActivity(); else if (path === 'plan') renderPlan(); else if (path === 'settings') renderSettings(); else if (path === 'reports') renderReports(); else if (path === 'calendar') renderCalendar(); else if (path.startsWith('sources/')) renderSource(path.split('/')[1]); else renderOverview(); }
window.addEventListener('hashchange', () => { route = location.hash.slice(2) || 'overview'; render(); });
store.subscribe(render);
render();
refreshRates();
